Action.ExecScriptExpression:
using System;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;

var m = new ZoneServerModule();
m.Scan();
Triggernometry.Utilities.Memory.RegisterXivProcUpdatedAction(nameof(ZoneServerModule), m.Scan);
m.RegisterAnnotatedMethods();

public class ZoneServerModule : ModuleBase
{
    public IntPtr ContentReplyManagerPtr;
    public IntPtr ZoneServerIdOffsetPtr;

    public int ZoneServerIdOffset;

    public ZoneServerModule()
    {
        ScanMethod = () =>
        {
            // https://github.com/AtmoOmen/OmenTools/blob/main/OmenService/Implementations/Infos/GameState.Internal.cs
            // private static readonly CompSig ContentReplyManagerSig
            ContentReplyManagerPtr = Scanner.TryScan(
                "48 8D 0D * * * * E8 ?? ?? ?? ?? 45 33 C0 48 8D 57 ?? 41 8B CE E8 ?? ?? ?? ?? 48 8D 8F",
                nameof(ContentReplyManagerPtr));

            // 要读取开头的 ?? ?? ?? ?? 对应的值
            // private static readonly CompSig ZoneServerIDOffsetSig
            ZoneServerIdOffsetPtr = Scanner.TryScan(
                "0F 11 83 ?? ?? ?? ?? 0F 10 4F ?? 0F 11 8B ?? ?? ?? ?? 0F 10 47 ?? 0F 11 83 ?? ?? ?? ?? 0F 10 4F ?? 0F 11 8B ?? ?? ?? ?? 0F 10 47 ?? 0F 11 83 ?? ?? ?? ?? 0F 10 4F ?? 0F 11 8B ?? ?? ?? ?? 0F 10 47 ?? 0F 11 83 ?? ?? ?? ?? 0F 10 4F",
                nameof(ZoneServerIdOffsetPtr));

            if (ZoneServerIdOffsetPtr != IntPtr.Zero)
            {
                ZoneServerIdOffset = Memory.Read<int>(ZoneServerIdOffsetPtr + 3);
            }
        };
    }

    [ScriptingMethod("GetServerId")]
    public ushort GetServerId() // 通常为几十
    {
        if (ContentReplyManagerPtr == IntPtr.Zero || ZoneServerIdOffset == 0)
            return 0; // 防止频繁调用持续出错

        var packet = ContentReplyManagerPtr + ZoneServerIdOffset;
        return Memory.Read<ushort>(packet);
    }

    [ScriptingMethod("GetInstanceId")]
    public ushort GetInstanceId() // 通常为 0, 1 等较小数值
    {
        if (ContentReplyManagerPtr == IntPtr.Zero || ZoneServerIdOffset == 0)
            return 0;

        var packet = ContentReplyManagerPtr + ZoneServerIdOffset;
        return Memory.Read<ushort>(packet + 4);
    }
}

