Action.ExecScriptExpression:
using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using Triggernometry.Core;
using Triggernometry.Expressions.String.Models;
using Triggernometry.Expressions.String.Utils;
using Triggernometry.PluginBridges.BridgeNamazu.Vfx;
using Triggernometry.Utilities.Maths;
using static Triggernometry.Core.Scripting.ScriptHelper;

MineSweeper.RegisterNamedCallbacks();

// 核心逻辑备注
// 
// 防止注册回调与 Init/ChangeMap 的竞态（插件刚加载时 C# 回调尚未注册、NamedCallback 调用会直接丢失）：
//   触发器负责在调用 Init 和 ChangeMap 前分别把参数缓存到 Field_Minesweeper_Data 和 Field_Minesweeper_Map，
//   注册全部回调后会按 Init → ChangeMap 的顺序检查并消费这两个缓存；
//   此外两个缓存在两个回调正常执行后也会删除。
// 
// 防止 Init 与 ChangeMap 的竞态：
//   如果 ChangeMap 已经在 Init 之前进入 C#，ChangeMap 不报错，而是把完整命令暂存在 _pendingMapCommand，
//   等 Init 完成后自动 ApplyMap。
// 
// Init 负责解析当前副本的整套雷区文本；
// ApplyMap 负责区域切换，新区域初始化对应 MineGroup 的 VFX，随后清理上一地区 VFX；
// ResetMap 用于某区域雷全部随机复原的机制（无论是否在区域内均可使用）。
//
// 每个雷的 Exist=null/true/false 分别表示未知/确认存在/确认不存在，
// ShownByGame 表示游戏已经显示或引爆该雷、不再需要辅助 VFX。
// Scan 会把扫描范围内尚未知的候选雷标记为不存在，Found 会按位置和大小雷类型确认具体雷存在。
//
// 每次状态变化后 MineGroup.AnalyzeState 根据 MaxCount 推断剩余候选雷，
// 当已确认存在的雷达到 MaxCount 时，其余候选全部判为不存在，并同步更新 VFX 显示状态。

// 调试模式：触发器标量变量 debug = 1

// 回调参数：

// Field_Minesweeper_Init:
// （整套雷区文本，详见下文注释）

// Field_Minesweeper_ChangeMap:
// 　Map: （Init 定义的区域名）

// Field_Minesweeper_Scan:
// 　Pos: x, y, z
// 　Range: r（输入整数即可，程序会减去网络包近似带来的坐标误差）

// Field_Minesweeper_Found:
// 　Pos: x, y, z
// 　IsLarge: 0/1

// Field_Minesweeper_ResetMap:
// 　Map: （Init 定义的区域名）

// Field_Minesweeper_End:
// 　（无参数）

public static class MineSweeper
{
    /// <summary> 缓存的 Init 数据变量名，Init 后删除此变量，注册后若此变量存在则立即以此执行 Init。</summary>
    private const string PendingInitDataVarName = "Field_Minesweeper_Data";
    /// <summary> 缓存的 ChangeMap 数据变量名，ChangeMap 后删除此变量，注册后若此变量存在则立即以此执行 ChangeMap。</summary>
    private const string PendingMapNameVarName = "Field_Minesweeper_Map";

    /// <summary>
    /// key：注册的区域名（如 F7a_15）；
    /// value：该区域的雷组列表
    /// </summary>
    private static Dictionary<string, List<MineGroup>> _mineData;
    private static readonly object _lock = new object();

    public static void RegisterNamedCallbacks()
    { 
        lock (_lock)
        {
            RegisterNamedCallback("Field_Minesweeper_Init", Init);
            RegisterNamedCallback("Field_Minesweeper_ChangeMap", ChangeMap);
            RegisterNamedCallback("Field_Minesweeper_Scan", Scan);
            RegisterNamedCallback("Field_Minesweeper_Found", Found);
            RegisterNamedCallback("Field_Minesweeper_ResetMap", ResetMap);
            RegisterNamedCallback("Field_Minesweeper_End", End);

            // 防止插件刚加载时，尚未注册回调就收到了 Init 或 ChangeMap 命令，导致数据丢失
            // 故 Init/ChangeMap 回调执行前会缓存数据，注册后如果有缓存的数据则立刻执行

            var pendingInitData = GetScalarVariable(false, PendingInitDataVarName);
            if (pendingInitData != null)
            {
                DebugLog($"Init after registration");
                Init(pendingInitData);
            }

            var pendingMapName = GetScalarVariable(false, PendingMapNameVarName);
            if (pendingMapName != null)
            {
                DebugLog($"ChangeMap after registration");
                ChangeMap($"Map: {pendingMapName}");
            }
        }
    }

    public static void RegisterNamedCallback(string callbackName, Action<string> action)
    {
        RealPlugin.Instance.RegisterNamedCallback(
            callbackName, 
            new Action<object, string>((_, cmd) => {
                lock (_lock) action(cmd);
            }), 
            null, 
            false, 
            "宝宝椅");
    }

    internal static void Init(string command)
    {
        DebugLog($"Init");

        if (_mineData != null)
        {
            DebugLog($"Init: ClearMineData");
            ClearMineData();
        }

        _prevMapName = null;
        _mineData = MineDataParser.Parse(command);

        SetScalarVariable(false, PendingInitDataVarName, null);

        // 如果 Init 还没完成时，ChangeMap 被调用了，则在此执行暂存的命令
        if (_pendingMapCommand != null)
        {
            DebugLog($"{nameof(_pendingMapCommand)} consumed");
            var pending = _pendingMapCommand;
            _pendingMapCommand = null;
            ApplyMap(pending);
        }
    }

    private static string _prevMapName;
    private static string _pendingMapCommand;

    /// <summary>
    /// 额外包装一层 ApplyMap，防止 Init 和 Change 同时调用的竞态问题。
    /// Init 还没完成时，Change 会暂存命令，等 Init 完成后再执行。
    /// </summary>
    internal static void ChangeMap(string command)
    {
        DebugLog($"ChangeMap: {command}");
        if (_mineData == null)
        {
            DebugLog($"{nameof(_pendingMapCommand)} recorded");
            _pendingMapCommand = command;
            return;
        }

        ApplyMap(command);
    }

    private static void ApplyMap(string command)
    {
        var data = new MultiLineRawArgs(command);
        var mapName = data.Get("map");
        DebugLog($"ApplyMap: {_prevMapName ?? "null"} → {mapName}");

        if (_prevMapName != mapName) // 允许在两张共享雷区的地图间调用回调，此时跳过，不做任何处理
        {
            // 加载新地图的雷特效
            if (_mineData.TryGetValue(mapName, out var currGroups))
                currGroups.ForEach(g => g.InitVfx());
            else if (mapName != "_")
                throw new Exception($"地图名称 {mapName} 未在雷组数据中定义。");

            // 清理旧地图的雷特效
            if (_prevMapName != null && _mineData.TryGetValue(_prevMapName, out var prevGroups))
                prevGroups.ForEach(g => g.RemoveVfx());

            _prevMapName = mapName;
        }

        SetScalarVariable(false, PendingMapNameVarName, null);
    }

    internal static void Scan(string command)
    {
        if (_mineData == null) return;

        var data = new MultiLineRawArgs(command);
        var pos = (Vector3)XIVCoord.ParseRawData(data.Get("pos"));
        var range = data.Get("range").ParseData<float>(); // 魔猎鹰半径 5 + 雷半径 4 = 9；探测半径 15 以雷中心为准
        DebugLog($"Scan: {pos}, {range}");

        foreach (var group in _mineData.SelectMany(pair => pair.Value))
        {
            group.TryApplyScan(pos, range);
        }
    }

    internal static void Found(string command)
    {
        if (_mineData == null) throw new Exception($"尚未使用 InitMineData 初始化雷组数据。");

        var data = new MultiLineRawArgs(command);
        var pos = (Vector3)XIVCoord.ParseRawData(data.Get("pos"));
        var isLarge = data.Get("isLarge").ParseData<bool>();
        DebugLog($"Found: {pos}, {isLarge}");

        foreach (var group in _mineData.SelectMany(pair => pair.Value))
        {
            if (group.Found(pos, isLarge) != null)
            {
                break;
            }
        }
    }

    internal static void ResetMap(string command)
    {
        if (_mineData == null)
            return;

        var data = new MultiLineRawArgs(command);
        var mapName = data.Get("map");
        DebugLog($"ResetMap: {mapName}");

        if (!_mineData.TryGetValue(mapName, out var groups))
            throw new Exception($"地图名称 {mapName} 未在雷组数据中定义。");

        foreach (var group in groups)
            group.ResetState();
    }

    internal static void End(string _ = null)
    {
        DebugLog($"End");

        ClearMineData();

        _pendingMapCommand = null;
        SetScalarVariable(false, PendingInitDataVarName, null);
        SetScalarVariable(false, PendingMapNameVarName, null);
    }

    private static void ClearMineData()
    {
        if (_mineData != null)
        {
            try
            {
                foreach (var group in _mineData.SelectMany(pair => pair.Value))
                    group.RemoveVfx();
            }
            catch (Exception ex)
            {
                ErrorLog($"清理雷组数据时发生异常，如游戏崩溃，建议重启 ACT：{ex}");
            }
            finally
            {
                _mineData = null;
            }
        }
        
        _prevMapName = null;
    }

    private static void DebugLog(string msg)
    {
        if (GetScalarVariable(false, "debug")?.ToString().ParseData<bool>() != true) return;
        RealPlugin.Instance.InvokeNamedCallback("command", $"/e [Debug] {msg}");
    }
}

internal static class MineDataParser
{
    private const string InitDataExample = @"
// 数据按行分割
// 可以包含空行，行首尾可以有空白字符
// 行中可以有 // 开头的注释
// [区域名] 是切换区域的回调需要传入的名称，不能重复
[F7a_15]
// (n) 代表雷组最大雷数 
(2)
// 7L/7S 代表 7.0 新月岛的大/小雷
7L: 100, 100, 0
7S: 110, 100, 0
7S: 120, 100, 0
7S: 130, 100, 0
(1)
7S: 100, 110, 0
7S: 110, 110, 0
[F7a_25]
(1)
7S: 100, 120, 0
7S: 110, 120, 0";

    internal static Dictionary<string, List<MineGroup>> Parse(string raw)
    {
        var result = new Dictionary<string, List<MineGroup>>();

        var lines = raw
            .Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(line =>
            {
                var idx = line.IndexOf("//");
                return idx >= 0 ? line.Substring(0, idx).Trim() : line.Trim();
            })
            .Where(line => !string.IsNullOrWhiteSpace(line));

        string region = null;
        int? maxCount = null;
        var groupLines = new List<string>();

        foreach (var line in lines)
        {
            // 新区域
            if (line.StartsWith("["))
            {
                // 先提交上一个雷组
                if (maxCount.HasValue)
                {
                    result[region].Add(ParseMineGroup(maxCount.Value, groupLines));
                    maxCount = null;
                    groupLines.Clear();
                }

                if (!line.EndsWith("]"))
                    throw new FormatException($"数据行 \"{line}\" 区域定义格式错误。示例：{InitDataExample}");

                region = line.Substring(1, line.Length - 2).Trim();

                if (string.IsNullOrWhiteSpace(region))
                    throw new FormatException($"数据行 \"{line}\" 的区域名不能为空。示例：{InitDataExample}");

                if (result.ContainsKey(region))
                    throw new FormatException($"区域 \"{region}\" 重复定义。示例：{InitDataExample}");

                result.Add(region, new List<MineGroup>());
                continue;
            }

            if (region == null)
                throw new FormatException($"数据行 \"{line}\" 前缺少区域定义。示例：{InitDataExample}");

            // 新雷组
            if (line.StartsWith("("))
            {
                // 遇到下一个组时提交上一个组
                if (maxCount.HasValue)
                {
                    result[region].Add(ParseMineGroup(maxCount.Value, groupLines));
                    groupLines.Clear();
                }

                if (!line.EndsWith(")"))
                    throw new FormatException($"数据行 \"{line}\" 雷组数量格式错误。示例：{InitDataExample}");

                var countText = line.Substring(1, line.Length - 2).Trim();
                if (!int.TryParse(countText, out int count) || count <= 0)
                    throw new FormatException($"数据行 \"{line}\" 无法解析雷组最大雷数。示例：{InitDataExample}");

                maxCount = count;
                continue;
            }

            if (!maxCount.HasValue)
                throw new FormatException($"数据行 \"{line}\" 前缺少雷组数量定义。示例：{InitDataExample}");

            groupLines.Add(line);
        }

        // 提交最后一组
        if (maxCount.HasValue)
            result[region].Add(ParseMineGroup(maxCount.Value, groupLines));

        return result;
    }


    // 解析一组雷，格式（无冗余行和注释）：
    // 7L: 100, 100, 0
    // 7S: 110, 100, 0
    // 7S: 110, 100, 0
    // 7S: 110, 120, 0
    private static MineGroup ParseMineGroup(int maxCount, List<string> lines)
    {
        if (lines.Count < maxCount)
            throw new FormatException($"提供的雷数量 {lines.Count} 少于最大雷数 {maxCount}。");

        var mines = new List<Mine>();

        foreach (var line in lines)
        {
            var parts = line.Split(new[] { ':' }, 2);
            if (parts.Length != 2)
                throw new FormatException($"无法解析雷数据，格式应如“类型: x, y, z”：{line}");

            // 以后可能改，暂时只支持 7.0 副本
            var type = parts[0].Trim();
            bool isLarge;
            switch (type)
            {
                case "7L":
                    isLarge = true;
                    break;
                case "7S":
                    isLarge = false;
                    break;
                default:
                    throw new FormatException($"数据行 {line} 含有未知雷类型：{type}");
            }

            var (x, y, z) = parts[1].ParseArgs<double, double, double>();
            mines.Add(new Mine(x, y, z, isLarge));
        }

        return new MineGroup(maxCount, mines);
    }
}

internal class MineGroup
{
    //public bool IsLarge => Mines.First().IsLarge;
    internal int MaxCount { get; set; }
    internal List<Mine> Mines { get; set; }
    internal bool Resolved { get; set; }
    internal MineGroup(int maxCount, IEnumerable<Mine> mines)
    {
        Mines = mines.ToList();
        MaxCount = maxCount;
    }

    internal MineGroup(int maxCount, params (double, double, double, bool)[] minesData)
    {
        Mines = minesData.Select(data => new Mine(data)).ToList();
        MaxCount = maxCount;
    }

    internal void InitVfx()
    {
        Mines.ForEach(m => m.InitVfx());
    }

    internal void UpdateVfxByState()
    {
        Mines.ForEach(m => m.UpdateVfxByState());
    }

    internal void RemoveVfx()
    {
        Mines.ForEach(m => m.RemoveVfx());
    }

    private void AnalyzeState()
    {
        var exist = new List<Mine>();
        var others = new List<Mine>();

        foreach (var m in Mines)
        {
            if (m.Exist == true)
                exist.Add(m);
            else
                others.Add(m);
        }

        if (exist.Count >= MaxCount)
        {
            foreach (var m in others)
            {
                m.Exist = false;
            }
        }
        if (exist.Count > MaxCount)
        {
            ErrorLog($"组内记录到的雷数高于最大数目：\n{string.Join("; \n", exist.Select(m => m.Pos))}");
        }
        UpdateVfxByState();
    }

    internal bool TryApplyScan(Vector3 scanPos, double range)
    {
        // 坐标可能有 0.1 m 误差
        var minesInRange = Mines.Where(mine => mine.IsInRange(scanPos, range - 0.1)).ToList();
        if (minesInRange.Any())
        {
            foreach (var m in minesInRange)
            {
                if (m.Exist == null)
                    m.Exist = false;
            }
            AnalyzeState();
            return true;
        }
        return false;
    }

    internal Mine Found(Vector3 pos, bool isLarge)
    {
        var minesInRange = Mines.Where(mine => mine.IsInRange(pos, 1) && isLarge == mine.IsLarge).ToList();
        if (minesInRange.Count > 1)
            throw new Exception("扫描到超过一个雷，疑似数据有误。");
        var foundMine = minesInRange.FirstOrDefault();
        if (foundMine != null)
        {
            foundMine.ShownByGame = true;
            foundMine.Exist = true;
            AnalyzeState();
        }
        return foundMine;
    }

    /// <summary> 重置状态为未知，且未被游戏显示。用于某些复原所有雷的机制。 </summary>
    internal void ResetState()
    {
        Resolved = false;

        foreach (var mine in Mines)
            mine.ResetState();
    }
}

internal class Mine
{
    private const string VFX_TAG = "Field_Minesweeper";
    private const string VFX_PATH = "vfx/omen/eff/m0777cir_a_o0c.avfx";
    internal float ExplodeRadius => IsLarge ? 30f : 7f; // 暂时没用
    internal Vector3 Pos { get; set; }
    internal bool IsLarge { get; set; }
    internal bool IsInRange(Vector3 knownPos, double range)
    {
        // 平面距离小于阈值，且高度差小于 10 m
        var dx = knownPos.X - Pos.X;
        var dy = knownPos.Y - Pos.Y;
        var dz = Math.Abs(knownPos.Z - Pos.Z);

        return dx * dx + dy * dy <= range * range && dz <= 10;
    }

    internal Mine(double x, double y, double z, bool isLarge)
    {
        Pos = new Vector3((float)x, (float)y, (float)z);
        IsLarge = isLarge;
    }
    internal Mine((double, double, double, bool) rawData)
        : this(rawData.Item1, rawData.Item2, rawData.Item3, rawData.Item4) { }

    // 状态相关：

    /// <summary> 是否可以确定其是否存在 </summary>
    internal bool? Exist { get; set; } = null;
    /// <summary> 是否已经被游戏显示（或已爆炸），即不需要再显示此特效 </summary>
    internal bool ShownByGame { get; set; } = false;

    /// <summary> 重置状态为未知，且未被游戏显示。用于某些复原所有雷的机制。 </summary>
    internal void ResetState()
    {
        Exist = null;
        ShownByGame = false;
        UpdateVfxByState();
    }

    // 特效相关：

    private StaticVfx _vfx;
    internal void InitVfx()
    {
        if (_vfx != null) RemoveVfx();
        _vfx = VfxManager.InitStatic(VFX_PATH, VFX_TAG);
        _vfx.Pos = Pos;
        _vfx.Scales = new Vector3(4, 4, 5);
        _vfx.Color = IsLarge
            ? new Vector4(1f, 0.4f, 0.7f, 1f)  // 红
            : new Vector4(0.7f, 1f, 0.2f, 1f); // 黄
        UpdateVfxByState();
    }

    internal void UpdateVfxByState()
    {
        if (_vfx == null || _vfx.Removed || _vfx.Ptr == IntPtr.Zero) return;
        bool shouldDisplay = Exist == false ? false : !ShownByGame;
        var color = _vfx.Color;
        color.W = shouldDisplay ? 1f : 0f;
        _vfx.Color = color;
        _vfx.Update();
    }

    internal void RemoveVfx()
    {
        _vfx?.TryRemove();
        _vfx = null;
    }

}

